{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01YWSgAb9iE6LdgZSopLT4uX","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01VyFUXLQSLvdebjUx9uoqNQ","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"seetacloud-rtx6000","command":"cat > /root/cert_manip_resist_eval/scripts/run_pool_a_mde.py << 'SCRIPT_EOF'\n#!/usr/bin/env python3\n\"\"\"Pool A MDE Power Analysis with Wild Cluster Bootstrap (Webb 6-point).\n\nFor K=3 (84 panels from C(9,3)) and K=5 (126 panels from C(9,5)),\ncompute power to detect K_eff effect at various standardized effect sizes.\n\"\"\"\n\nimport os\nimport sys\nimport json\nimport time\nimport itertools\nimport logging\nimport argparse\nimport numpy as np\nimport statsmodels.api as sm\nfrom pathlib import Path\nfrom scipy.interpolate import interp1d\n\n# ── Config ───────────────────────────────────────────────────────────\nMI_MODELS = [\n    \"qwen2.5-72b\", \"llama3.1-70b\", \"mistral-large\",\n    \"qwen2.5-32b\", \"qwen2.5-14b\", \"llama3.1-8b\",\n    \"claude-opus-4-6\", \"gpt-5.5\", \"gemini-3.1-pro-preview\", \"gpt-4.1\",\n    \"claude-sonnet-4-6\", \"gpt-4.1-nano\", \"gemini-3.5-flash\",\n    \"gpt-4.1-mini\", \"claude-3-haiku\",\n]\nPOOL_A = MI_MODELS[6:]  # 9 API-tier models\nPOOL_A_INDICES = list(range(6, 15))\n\nDATASETS = [\"mmlu\", \"arc_challenge\"]\nATTACKS = [\n    \"prompt_injection\", \"sycophancy\", \"score_manipulation\",\n    \"verbosity_bias\", \"position_bias\", \"authority_bias\",\n]\nEPS = 1e-6\nBETA_STD_GRID = [0.1, 0.15, 0.2, 0.25, 0.3]\nSEED = 42\n\n# Webb 6-point distribution: E[w]=0, E[w^2]=1\nWEBB_6 = np.array([\n    -np.sqrt(3/2), -1.0, -np.sqrt(1/2),\n     np.sqrt(1/2),  1.0,  np.sqrt(3/2),\n])\n\nBASE_DIR = Path(\"/root/cert_manip_resist_eval\")\nSCORES_DIR = BASE_DIR / \"artifacts/results/plan001/individual_scores\"\nMI_PATH = BASE_DIR / \"artifacts/results/plan001/mi_matrix/mi_matrix_15models.json\"\nCKPT_PATH = BASE_DIR / \"artifacts/results/_taxonomy_checkpoint.json\"\nOUT_PATH = BASE_DIR / \"artifacts/results/plan001/pool_a_mde.json\"\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s [%(levelname)s] %(message)s\",\n    datefmt=\"%H:%M:%S\",\n)\nlogger = logging.getLogger(\"pool_a_mde\")\n\n\ndef _json_default(obj):\n    if isinstance(obj, np.floating):\n        v = float(obj)\n        return None if (np.isnan(v) or np.isinf(v)) else v\n    if isinstance(obj, np.integer):\n        return int(obj)\n    if isinstance(obj, np.ndarray):\n        return obj.tolist()\n    if isinstance(obj, np.bool_):\n        return bool(obj)\n    raise TypeError(f\"Not JSON serializable: {type(obj)}\")\n\n\n# ── Data loading ─────────────────────────────────────────────────────\n\ndef load_mi_matrix():\n    with open(MI_PATH) as f:\n        data = json.load(f)\n    mi = {}\n    for ds in DATASETS:\n        mi[ds] = np.array(data[\"mi_matrix\"][ds])\n    return mi\n\n\ndef load_pairs():\n    with open(CKPT_PATH) as f:\n        data = json.load(f)\n    return {ds: data[\"pairs\"][ds][:300] for ds in DATASETS}\n\n\ndef load_individual_scores(model, dataset, condition):\n    path = SCORES_DIR / f\"{model}__{dataset}__{condition}.json\"\n    if not path.exists():\n        return None\n    with open(path) as f:\n        return json.load(f).get(\"scores\", [])\n\n\ndef load_pool_a_scores():\n    clean = {ds: {} for ds in DATASETS}\n    attacked = {ds: {a: {} for a in ATTACKS} for ds in DATASETS}\n    for m in POOL_A:\n        for ds in DATASETS:\n            scores = load_individual_scores(m, ds, \"clean\")\n            if scores:\n                clean[ds][m] = scores\n            for atk in ATTACKS:\n                scores = load_individual_scores(m, ds, atk)\n                if scores:\n                    attacked[ds][atk][m] = scores\n    return clean, attacked\n\n\n# ── K_eff computation ────────────────────────────────────────────────\n\ndef mi_based_keff(mi_matrix, model_indices):\n    K = len(model_indices)\n    if K <= 1:\n        return 1.0\n    keff = 0.0\n    for i_idx in model_indices:\n        term = 1.0\n        for j_idx in model_indices:\n            if i_idx != j_idx:\n                term += np.exp(-2 * mi_matrix[i_idx, j_idx])\n        keff += term\n    return keff / K\n\n\n# ── ASR computation ──────────────────────────────────────────────────\n\ndef _is_valid(s):\n    if s.get(\"error\") or s.get(\"format_error\"):\n        return False\n    return s.get(\"winner\") in (\"A\", \"B\", \"tie\")\n\n\ndef majority_vote(votes):\n    counts = {\"A\": 0, \"B\": 0, \"tie\": 0}\n    for v in votes:\n        counts[v] = counts.get(v, 0) + 1\n    mc = max(counts.values())\n    winners = [k for k, c in counts.items() if c == mc]\n    if len(winners) == 1:\n        return winners[0]\n    for w in winners:\n        if w != \"tie\":\n            return w\n    return \"tie\"\n\n\ndef compute_individual_asr(clean_list, attacked_list, pairs):\n    n = min(len(clean_list), len(attacked_list), len(pairs))\n    n_flips = n_correct = 0\n    for i in range(n):\n        if not _is_valid(clean_list[i]) or not _is_valid(attacked_list[i]):\n            continue\n        gt = pairs[i][\"ground_truth_winner\"]\n        if clean_list[i][\"winner\"] == gt:\n            n_correct += 1\n            if attacked_list[i][\"winner\"] != gt:\n                n_flips += 1\n    return n_flips / max(n_correct, 1)\n\n\ndef compute_panel_asr(jids, clean, attacked, pairs):\n    n = min(len(pairs), *(len(clean[j]) for j in jids),\n            *(len(attacked[j]) for j in jids))\n    n_flips = n_correct = 0\n    for i in range(n):\n        if not all(_is_valid(clean[j][i]) for j in jids):\n            continue\n        if not all(_is_valid(attacked[j][i]) for j in jids):\n            continue\n        gt = pairs[i][\"ground_truth_winner\"]\n        cv = majority_vote([clean[j][i][\"winner\"] for j in jids])\n        if cv != gt:\n            continue\n        n_correct += 1\n        av = majority_vote([attacked[j][i][\"winner\"] for j in jids])\n        if av != gt:\n            n_flips += 1\n    return n_flips / max(n_correct, 1)\n\n\n# ── Wild cluster bootstrap (vectorized, Webb 6-point) ────────────────\n\ndef wild_cluster_bootstrap_webb(y, X_full, cluster_ids, B, rng,\n                                test_col_idx=1):\n    n, p = X_full.shape\n    unique_clusters = np.unique(cluster_ids)\n    n_clusters = len(unique_clusters)\n    c2i = {c: i for i, c in enumerate(unique_clusters)}\n    panel_ci = np.array([c2i[c] for c in cluster_ids])\n\n    XtX_inv = np.linalg.inv(X_full.T @ X_full)\n    M_hat = XtX_inv @ X_full.T\n    beta_u = M_hat @ y\n    resid_u = y - X_full @ beta_u\n    sigma2_u = np.sum(resid_u ** 2) / (n - p)\n    t_obs = beta_u[test_col_idx] / np.sqrt(sigma2_u * XtX_inv[test_col_idx, test_col_idx])\n\n    cols_r = [i for i in range(p) if i != test_col_idx]\n    X_r = X_full[:, cols_r]\n    M_hat_r = np.linalg.inv(X_r.T @ X_r) @ X_r.T\n    beta_r = M_hat_r @ y\n    y_hat_r = X_r @ beta_r\n    e_r = y - y_hat_r\n\n    w_cluster = rng.choice(WEBB_6, size=(B, n_clusters))\n    w_panel = w_cluster[:, panel_ci]\n    Y_boot = y_hat_r[None, :] + w_panel * e_r[None, :]\n\n    Beta_boot = Y_boot @ M_hat.T\n    Resid_boot = Y_boot - Beta_boot @ X_full.T\n    sigma2_boot = np.sum(Resid_boot ** 2, axis=1) / (n - p)\n    se_boot = np.sqrt(sigma2_boot * XtX_inv[test_col_idx, test_col_idx])\n    se_boot = np.maximum(se_boot, 1e-15)\n    t_boot = Beta_boot[:, test_col_idx] / se_boot\n\n    p_value = (1 + np.sum(np.abs(t_boot) >= np.abs(t_obs))) / (1 + B)\n    return float(p_value), n_clusters\n\n\ndef bootstrap_K_positions(y, X_full, panel_jids_list, K, B, rng,\n                          test_col_idx=1):\n    position_ps = []\n    position_clusters = []\n    for pos in range(K):\n        cluster_ids = np.array([jids[pos] for jids in panel_jids_list])\n        p_val, n_cl = wild_cluster_bootstrap_webb(\n            y, X_full, cluster_ids, B, rng, test_col_idx\n        )\n        position_ps.append(p_val)\n        position_clusters.append(n_cl)\n    return position_ps, max(position_ps), position_clusters\n\n\n# ── Build panel data ─────────────────────────────────────────────────\n\ndef build_panel_data(K, mi_matrices, clean, attacked, pairs):\n    pool_indices = POOL_A_INDICES\n    combos = list(itertools.combinations(range(len(POOL_A)), K))\n    logger.info(f\"  K={K}: {len(combos)} panels from {len(POOL_A)} models\")\n\n    all_cond_data = {}\n    for ds in DATASETS:\n        mi_mat = mi_matrices[ds]\n        for atk in ATTACKS:\n            cond = f\"{ds}x{atk}\"\n            ds_clean = clean.get(ds, {})\n            ds_attacked = attacked.get(ds, {}).get(atk, {})\n            ds_pairs = pairs.get(ds, [])\n            if not ds_clean or not ds_attacked or not ds_pairs:\n                continue\n\n            ind_asr = {}\n            for m in POOL_A:\n                if m in ds_clean and m in ds_attacked:\n                    ind_asr[m] = compute_individual_asr(\n                        ds_clean[m], ds_attacked[m], ds_pairs\n                    )\n\n            p_asrs, p_keffs, p_etas = [], [], []\n            panel_jids_list = []\n\n            for combo in combos:\n                jids = [POOL_A[i] for i in combo]\n                if not all(j in ind_asr for j in jids):\n                    continue\n                if not all(j in ds_clean and j in ds_attacked for j in jids):\n                    continue\n\n                global_indices = [pool_indices[i] for i in combo]\n                keff = mi_based_keff(mi_mat, global_indices)\n                eta_max = max(ind_asr[j] for j in jids)\n                p_asr = compute_panel_asr(\n                    jids,\n                    {j: ds_clean[j] for j in jids},\n                    {j: ds_attacked[j] for j in jids},\n                    ds_pairs,\n                )\n\n                p_asrs.append(p_asr)\n                p_keffs.append(keff)\n                p_etas.append(eta_max)\n                panel_jids_list.append(jids)\n\n            n_panels = len(p_asrs)\n            if n_panels < 10:\n                continue\n\n            p_asrs = np.array(p_asrs)\n            if np.std(p_asrs) < 1e-10:\n                continue\n\n            log_keff = np.log(np.array(p_keffs))\n            log_eta = np.log(np.array(p_etas) + EPS)\n            y = np.log(p_asrs + EPS)\n\n            all_cond_data[cond] = {\n                \"y\": y,\n                \"log_keff\": log_keff,\n                \"log_eta\": log_eta,\n                \"panel_jids_list\": panel_jids_list,\n                \"n_panels\": n_panels,\n            }\n\n    logger.info(f\"  Built {len(all_cond_data)} conditions for K={K}\")\n    return all_cond_data\n\n\n# ── Power analysis ───────────────────────────────────────────────────\n\ndef run_mde_power(K, cond_data_dict, n_sim, n_boot, rng):\n    cond_keys = sorted(cond_data_dict.keys())\n    n_conds = len(cond_keys)\n    logger.info(f\"  Running power analysis: K={K}, {n_conds} conditions, \"\n                f\"{n_sim} sims, {n_boot} bootstrap reps\")\n\n    power_accum = {str(b): 0.0 for b in BETA_STD_GRID}\n\n    for ci, cond in enumerate(cond_keys):\n        data = cond_data_dict[cond]\n        y = data[\"y\"]\n        log_keff = data[\"log_keff\"]\n        log_eta = data[\"log_eta\"]\n        n_panels = data[\"n_panels\"]\n        panel_jids = data[\"panel_jids_list\"]\n\n        X = sm.add_constant(np.column_stack([log_keff, log_eta]))\n        fit = sm.OLS(y, X).fit()\n\n        intercept = fit.params[0]\n        beta_eta = fit.params[2]\n        sigma_resid = np.sqrt(fit.mse_resid)\n        sd_y = np.std(y)\n        sd_log_keff = np.std(log_keff)\n\n        if sd_log_keff < 1e-10:\n            continue\n\n        for beta_std in BETA_STD_GRID:\n            beta_raw = beta_std * sd_y / sd_log_keff\n            n_sig = 0\n\n            for sim in range(n_sim):\n                y_sim = (intercept\n                         + beta_raw * log_keff\n                         + beta_eta * log_eta\n                         + rng.normal(0, sigma_resid, n_panels))\n\n                _, final_p, _ = bootstrap_K_positions(\n                    y_sim, X, panel_jids, K, n_boot, rng, test_col_idx=1\n                )\n\n                if final_p < 0.05:\n                    n_sig += 1\n\n            power = n_sig / n_sim\n            power_accum[str(beta_std)] += power\n\n        logger.info(f\"    [{ci+1}/{n_conds}] {cond}: done \"\n                    f\"(n={n_panels}, R2={fit.rsquared:.3f})\")\n\n    power_avg = {}\n    for b in BETA_STD_GRID:\n        power_avg[str(b)] = round(power_accum[str(b)] / n_conds, 4)\n\n    betas = np.array(BETA_STD_GRID)\n    powers = np.array([power_avg[str(b)] for b in BETA_STD_GRID])\n    mde_80 = None\n    if powers[-1] >= 0.80 and powers[0] <= 0.80:\n        try:\n            f_interp = interp1d(powers, betas, kind='linear')\n            mde_80 = float(f_interp(0.80))\n        except Exception:\n            pass\n    elif powers[0] > 0.80:\n        mde_80 = float(betas[0])\n    elif powers[-1] < 0.80:\n        mde_80 = None\n\n    logger.info(f\"  K={K} power: {power_avg}\")\n    if mde_80 is not None:\n        logger.info(f\"  K={K} MDE@80%: {mde_80:.4f}\")\n    else:\n        logger.info(f\"  K={K} MDE@80%: not achievable (max power={powers[-1]:.3f})\")\n\n    return power_avg, mde_80\n\n\n# ── Main ─────────────────────────────────────────────────────────────\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--n-sim\", type=int, default=1000)\n    parser.add_argument(\"--n-boot\", type=int, default=999)\n    parser.add_argument(\"--dry-run\", action=\"store_true\")\n    args = parser.parse_args()\n\n    n_sim = 5 if args.dry_run else args.n_sim\n    n_boot = 99 if args.dry_run else args.n_boot\n\n    logger.info(\"=\" * 60)\n    logger.info(\"Pool A MDE Power Analysis\")\n    logger.info(f\"  n_sim={n_sim}, n_boot={n_boot}, seed={SEED}\")\n    logger.info(f\"  Pool A models: {POOL_A}\")\n    logger.info(\"=\" * 60)\n\n    t0 = time.time()\n    rng = np.random.default_rng(SEED)\n\n    logger.info(\"Loading data...\")\n    mi_matrices = load_mi_matrix()\n    pairs = load_pairs()\n    clean, attacked = load_pool_a_scores()\n\n    n_loaded = sum(1 for ds in DATASETS for m in POOL_A if m in clean[ds])\n    logger.info(f\"  Loaded {n_loaded} clean score sets\")\n\n    logger.info(\"\\nBuilding K=3 panel data...\")\n    data_k3 = build_panel_data(3, mi_matrices, clean, attacked, pairs)\n\n    logger.info(\"\\nBuilding K=5 panel data...\")\n    data_k5 = build_panel_data(5, mi_matrices, clean, attacked, pairs)\n\n    logger.info(\"\\n--- K=3 Power Analysis ---\")\n    power_k3, mde_k3 = run_mde_power(3, data_k3, n_sim, n_boot, rng)\n\n    logger.info(\"\\n--- K=5 Power Analysis ---\")\n    power_k5, mde_k5 = run_mde_power(5, data_k5, n_sim, n_boot, rng)\n\n    elapsed = time.time() - t0\n\n    output = {\n        \"pool_a_models\": POOL_A,\n        \"pool_a_panels\": {\n            \"K3\": len(list(itertools.combinations(range(9), 3))),\n            \"K5\": len(list(itertools.combinations(range(9), 5))),\n        },\n        \"beta_std_values\": BETA_STD_GRID,\n        \"n_simulations\": n_sim,\n        \"n_bootstrap\": n_boot,\n        \"bootstrap_weights\": \"webb_6point\",\n        \"seed\": SEED,\n        \"power_by_beta\": {\n            \"K3\": power_k3,\n            \"K5\": power_k5,\n        },\n        \"mde_at_80pct\": {\n            \"K3\": mde_k3,\n            \"K5\": mde_k5,\n        },\n        \"elapsed_seconds\": round(elapsed, 1),\n        \"notes\": (\n            \"Power averaged across 12 conditions (2 datasets x 6 attacks). \"\n            \"Wild cluster bootstrap with Webb 6-point weights, \"\n            f\"B={n_boot}, max p-value across K judge positions. \"\n            \"Regression: log(ASR+eps) ~ log(K_eff) + log(eta_max+eps).\"\n        ),\n    }\n\n   