a_eta={fit.params[2]:.4f}, t={fit.tvalues[2]:.3f}, p={fit.pvalues[2]:.6f}')\nprint(f'  R2={fit.rsquared:.4f}, sigma={np.sqrt(fit.mse_resid):.4f}')\nprint(f'  SD(y)={np.std(y):.4f}, SD(lk)={np.std(lk):.4f}')\n\n# Test wild cluster bootstrap on actual data\nWEBB_6 = np.array([-np.sqrt(3/2), -1.0, -np.sqrt(1/2), np.sqrt(1/2), 1.0, np.sqrt(3/2)])\nrng = np.random.default_rng(42)\n\n# Position 0 clustering\ncids = np.array([j[0] for j in jids_list])\nunique_c = np.unique(cids)\nprint(f'\\\\nPosition 0: {len(unique_c)} clusters')\nc2i = {c:i for i,c in enumerate(unique_c)}\npci = np.array([c2i[c] for c in cids])\n\nn,p = X.shape\nXtX_inv = np.linalg.inv(X.T @ X)\nM = XtX_inv @ X.T\nbeta_u = M @ y\nresid_u = y - X @ beta_u\ns2 = np.sum(resid_u**2)/(n-p)\nt_obs = beta_u[1]/np.sqrt(s2*XtX_inv[1,1])\nprint(f't_obs(keff) = {t_obs:.3f}')\n\n# Restricted model\nXr = X[:, [0,2]]\nMr = np.linalg.inv(Xr.T@Xr) @ Xr.T\nbr = Mr @ y\nyr = Xr @ br\ner = y - yr\n\nB = 999\nwc = rng.choice(WEBB_6, size=(B, len(unique_c)))\nwp = wc[:, pci]\nYb = yr[None,:] + wp * er[None,:]\nBb = Yb @ M.T\nRb = Yb - Bb @ X.T\ns2b = np.sum(Rb**2, axis=1)/(n-p)\nseb = np.sqrt(s2b * XtX_inv[1,1])\nseb = np.maximum(seb, 1e-15)\ntb = Bb[:,1]/seb\n\npval = (1+np.sum(np.abs(tb)>=np.abs(t_obs)))/(1+B)\nprint(f'bootstrap p(pos0) = {pval:.4f}')\nprint(f't_boot stats: mean={tb.mean():.3f}, std={tb.std():.3f}, max={np.abs(tb).max():.3f}')\nprint(f'|t_obs|={abs(t_obs):.3f}, frac |t_boot|>|t_obs|: {np.mean(np.abs(tb)>=abs(t_obs)):.4f}')\n\n# Now test with simulated y (beta_std=0.3)\nsd_y = np.std(y)\nsd_lk = np.std(lk)\nbeta_raw = 0.3 * sd_y / sd_lk\nsigma = np.sqrt(fit.mse_resid)\ny_sim = fit.params[0] + beta_raw*lk + fit.params[2]*le + rng.normal(0, sigma, n)\n\nbeta_sim = M @ y_sim\nresid_sim = y_sim - X @ beta_sim\ns2_sim = np.sum(resid_sim**2)/(n-p)\nt_sim = beta_sim[1]/np.sqrt(s2_sim*XtX_inv[1,1])\nprint(f'\\\\nSimulated y (beta_std=0.3, beta_raw={beta_raw:.3f}):')\nprint(f'  t_obs(sim) = {t_sim:.3f}')\n\n# Bootstrap on simulated\nbr_sim = Mr @ y_sim\nyr_sim = Xr @ br_sim\ner_sim = y_sim - yr_sim\n\nwc2 = rng.choice(WEBB_6, size=(B, len(unique_c)))\nwp2 = wc2[:, pci]\nYb2 = yr_sim[None,:] + wp2 * er_sim[None,:]\nBb2 = Yb2 @ M.T\nRb2 = Yb2 - Bb2 @ X.T\ns2b2 = np.sum(Rb2**2, axis=1)/(n-p)\nseb2 = np.sqrt(s2b2 * XtX_inv[1,1])\nseb2 = np.maximum(seb2, 1e-15)\ntb2 = Bb2[:,1]/seb2\n\npval2 = (1+np.sum(np.abs(tb2)>=np.abs(t_sim)))/(1+B)\nprint(f'  bootstrap p(sim, pos0) = {pval2:.4f}')\nprint(f'  t_boot stats: mean={tb2.mean():.3f}, std={tb2.std():.3f}')\n\" 2>&1"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":3220,"cache_read_input_tokens":121896,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":3220},"output_tokens":9,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"671bb6a7-0ff4-4429-abec-efd39c0ca85e","uuid":"4aab158c-66cd-47c2-960f-453afdadf8f1"}
