"beta_std_values\": BETA_STD_GRID,\n        \"n_simulations\": n_sim,\n        \"n_bootstrap\": n_boot,\n        \"bootstrap_weights\": \"webb_6point\",\n        \"seed\": SEED,\n        \"clusters_per_position\": {\n            \"K3\": ref_k3[\"n_clusters_per_pos\"],\n            \"K5\": ref_k5[\"n_clusters_per_pos\"],\n        },\n        \"power_by_beta\": {\n            \"K3\": power_k3,\n            \"K5\": power_k5,\n        },\n        \"mde_at_80pct\": {\n            \"K3\": mde_k3,\n            \"K5\": mde_k5,\n        },\n        \"elapsed_seconds\": round(elapsed, 1),\n        \"notes\": (\n            \"Power per-condition then averaged across 12 conditions \"\n            \"(2 datasets x 6 attacks). \"\n            \"Wild cluster bootstrap with Webb 6-point weights, \"\n            f\"B={n_boot}, max p-value across K judge positions. \"\n            \"Regression: log(ASR+eps) ~ log(K_eff) + log(eta_max+eps). \"\n            \"Few clusters per position (7 for K=3, 5 for K=5) make WCB \"\n            \"very conservative, limiting power.\"\n        ),\n    }\n\n    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)\n    with open(OUT_PATH, \"w\") as f:\n        json.dump(output, f, indent=2, default=_json_default, ensure_ascii=False)\n    logger.info(f\"\\nSaved: {OUT_PATH}\")\n    logger.info(f\"Total time: {elapsed:.1f}s\")\n\n\nif __name__ == \"__main__\":\n    main()\nSCRIPT_EOF"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":4133,"cache_read_input_tokens":125116,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":4133},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"671bb6a7-0ff4-4429-abec-efd39c0ca85e","uuid":"02805679-dbd1-4547-8d40-74d1cfb2fb56"}
